!function(){function t(t){return function(t){if(Array.isArray(t))return e(t)}(t)||function(t){if("undefined"!=typeof Symbol&&null!=t[Symbol.iterator]||null!=t["@@iterator"])return Array.from(t)}(t)||function(t,r){if(t){if("string"==typeof t)return e(t,r);var n={}.toString.call(t).slice(8,-1);return"Object"===n&&t.constructor&&(n=t.constructor.name),"Map"===n||"Set"===n?Array.from(t):"Arguments"===n||/^(?:Ui|I)nt(?:8|16|32)(?:Clamped)?Array$/.test(n)?e(t,r):void 0}}(t)||function(){throw new TypeError("Invalid attempt to spread non-iterable instance.\nIn order to be iterable, non-array objects must have a [Symbol.iterator]() method.")}()}function e(t,e){(null==e||e>t.length)&&(e=t.length);for(var r=0,n=Array(e);r<e;r++)n[r]=t[r];return n}System.register(["./index-legacy-C_nr1GkG.js"],function(e,r){"use strict";var n,i,o,p,s,m;return{setters:[function(t){n=t.G,i=t.c,o=t.a,p=t.b,s=t.d,m=t.o}],execute:function(){var r={class:"cm-art-container",itemscope:"",itemtype:"https://schema.org/Article"};e("default",n({__name:"article",setup:function(e){return function(e,n){return m(),i("div",r,t(n[0]||(n[0]=[o('<h2 class="cm-art-title" itemprop="headline">新消息头像制作：还原微信风格的未读消息角标</h2><p class="cm-art-desc" itemprop="description">快速生成带消息数角标的微信风格头像，支持直角/圆角样式、自定义消息数量，一键导出高清图片。</p><section class="cm-art-section"><h3>从「小红点」到「数字角标」的设计演进</h3><p>消息通知角标（Notification Badge）是移动端 UI 设计中最经典也最有效的信息密度增强手段之一。它的核心价值在于：<strong>在不打开应用的前提下传递「有待处理事项」的信息</strong>。从早期的纯红点（仅表示「有新内容」）到现在的数字角标（精确显示数量），这个小小的设计元素经历了近十年的迭代优化。</p><p>微信的头像+角标组合尤其具有标志性意义：右上角的红色圆角矩形背景 + 白色数字，已经成为中文互联网用户心中「有新消息」的视觉代名词。这种设计被广泛应用于 App 图标、头像、导航栏等各种场景，甚至衍生出了表情包和社交文化现象（如「99+」的幽默用法）。</p></section><section class="cm-art-section"><h3>制作流程与参数说明</h3><p>使用本工具生成消息头像只需三步：</p><ol><li><strong>上传基础头像</strong>——支持 JPG/PNG/GIF 格式，建议使用正方形图片以获得最佳效果。如果原图不是正方形，工具会自动居中裁剪为正方形。</li><li><strong>设置消息数量</strong>——输入 1-999 之间的任意整数。输入 0 时不显示角标（即纯净头像）；超过 99 时自动显示为「99+」（与微信行为一致）。</li><li><strong>选择头像样式</strong>——提供<strong>直角</strong>和<strong>圆角</strong>两种选项。直角风格更接近早期微信的硬朗设计；圆角则匹配当前版本的圆润审美。输出尺寸为 512×512 像素，足够用于各种场景（高清屏幕显示、打印等）。</li></ol></section>',4),p("section",{class:"cm-art-faq",itemscope:"",itemtype:"https://schema.org/FAQPage"},[p("h3",null,"常见问题"),p("details",{itemprop:"mainEntity",itemtype:"https://schema.org/Question"},[p("summary",{itemprop:"name"},"生成的头像可以直接用作微信头像吗？"),p("div",{itemprop:"acceptedAnswer",itemtype:"https://schema.org/Answer"},[p("p",{itemprop:"text"},[s("可以，但需要注意："),p("strong",null,"微信头像的展示区域是圆形的"),s("（在大多数界面中），而本工具输出的画布是方形的。如果你将带角标的方形图直接设置为微信头像，四个角会被裁剪掉——好在角标位于右上角区域，圆形裁剪后通常仍能完整保留角标的大部分或全部。建议在设置前先用圆形裁剪工具预览实际效果。另外，微信会对上传的头像进行压缩处理，512px 的原图会被缩小到约 200px 显示，所以即使原图很清晰，在微信内看到的版本也会有一定程度的模糊——这是平台限制，无法避免。")])])]),p("details",{itemprop:"mainEntity",itemtype:"https://schema.org/Question"},[p("summary",{itemprop:"name"},"可以自定义角标的颜色和位置吗？"),p("div",{itemprop:"acceptedAnswer",itemtype:"https://schema.org/Answer"},[p("p",{itemprop:"text"},"当前版本使用的是微信标准配色方案（红色背景 #FA5151、白色文字），位置固定在右上角。这是为了最大程度还原微信原生效果。如果你需要其他颜色方案（如蓝色代表企业微信、绿色代表已读状态），或者需要调整角标大小和位置（如做类似 iOS 通知中心的效果），目前可以通过下载 PNG 后用图像编辑软件手动修改。未来版本可能会加入颜色选择器和位置调节功能。")])]),p("details",{itemprop:"mainEntity",itemtype:"https://schema.org/Question"},[p("summary",{itemprop:"name"},"支持批量生成不同数量的头像吗？"),p("div",{itemprop:"acceptedAnswer",itemtype:"https://schema.org/Answer"},[p("p",{itemprop:"text"},"当前版本每次生成一张图片。如果你需要一组不同数量的头像（如 1-10 各一张），需要逐次修改数字并生成/保存。一个效率技巧：先确定好所有需要的数字，然后按顺序快速修改 → 回车触发渲染 → 右键保存，熟练后每张只需 3-5 秒。后续版本考虑加入「批量模式」——一次输入多个数字（逗号分隔），自动生成并打包为 ZIP 下载。")])]),p("details",{itemprop:"mainEntity",itemtype:"https://schema.org/Question"},[p("summary",{itemprop:"name"},"这个工具可以用来做什么？有哪些实际用途？"),p("div",{itemprop:"acceptedAnswer",itemtype:"https://schema.org/Answer"},[p("p",{itemprop:"text"},[s("用途比想象中丰富：（1）"),p("strong",null,"社交媒体内容创作"),s("——制作「未读消息」主题的表情包或段子图；（2）"),p("strong",null,"UI 设计稿"),s("——产品经理或设计师在做原型时需要模拟真实的消息通知状态；（3）"),p("strong",null,"教学演示"),s("——讲解 App 设计规范时的示例素材；（4）"),p("strong",null,"个人娱乐"),s("——开玩笑式地告诉朋友「你有一条未读消息」，或者把 999+ 头像发给对方制造惊喜/惊吓；（5）"),p("strong",null,"视频素材"),s("——作为短视频的封面图或过渡画面。")])])]),p("details",{itemprop:"mainEntity",itemtype:"https://schema.org/Question"},[p("summary",{itemprop:"name"},"透明背景的头像可以用吗？"),p("div",{itemprop:"acceptedAnswer",itemtype:"https://schema.org/Answer"},[p("p",{itemprop:"text"},"支持 PNG 透明背景图片作为输入素材。但需要注意的是，最终输出的画布背景是不透明的（白色或根据头像边缘填充）。如果你的原始头像本身是透明的（如 PNG 去底图后的 logo），合成后会自动填充白色背景以保证角标的红色能正常显示（红色在透明背景上可能影响可读性）。如果你确实需要透明背景的输出结果，可以在下载后用抠图工具将白色背景去除。")])]),p("details",{itemprop:"mainEntity",itemtype:"https://schema.org/Question"},[p("summary",{itemprop:"name"},"手机上操作方便吗？"),p("div",{itemprop:"acceptedAnswer",itemtype:"https://schema.org/Answer"},[p("p",{itemprop:"text"},"非常方便——甚至可以说手机是更自然的使用场景。操作路径：打开相册 → 选择照片 → 上传到工具 → 输入消息数 → 预览 → 长按保存到相册 → 直接设为微信头像。整个流程在 30 秒内即可完成，不需要安装任何 App。这也是「纯前端在线工具」的核心优势之一——随时随地可用，不占手机存储空间。")])])],-1)])))}}}))}}})}();
